package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaHaDraft5 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_subbuhun_quddus" to DuaText("Subbuhun Quddus (Ruku & Sujood)", "(Allah) Tsarki ya tabbata a gare shi, Mai tsarki, Ubangijin Mala'iku da Ruhi (Jibrilu).", "A cikin ruku da sujood.", "Annabi ﷺ ya karanta wannan cikin ruku'u da sujud."),
        "dua_sujood_dhanbi_kullah" to DuaText("A cikin Sujood: Ka Gafarta Dukkan Zunubaina", "Ya Allah Ka gafarta mini zunubaina - kanana da babba, na farko da na karshe, na bayyane da na boye.", "In sujood.", "Sujjada wuri ne da ake amsa addu'o'i."),
        "dua_sujood_ridaka" to DuaText("Mafaka cikin Jin dadin ku", "Ya Allah ina neman tsarinka da yardarka daga fushinka, da gafararka daga azabarka, kuma ina neman tsarinka daga gareka. Ba zan iya cikar yabonka ba; Kai ne kamar yadda Ka yabi Kanka.", "A cikin sujood - Aisha (RA) ta ji Annabi ﷺ yana fadin haka.", "Addu'ar Annabi ﷺ."),
        "dua_tashahhud" to DuaText("Tashahhud (At-Tahiyyat)", "Dukkan ibadar baki da ta jiki da ta kudi ta Allah ce. Amincin Allah ya tabbata a gareka ya Annabi, da rahamar Allah da albarkarSa. Amincin Allah ya tabbata a gare mu da bayin Allah salihai. Ina shaidawa babu abin bautawa da gaskiya sai Allah, kuma ina shaidawa Muhammadu ﷺ bawansa ne kuma manzonsa ne.", "A kowane zama - Abdullahi bn Mas'ud ya ruwaito (RA) (aikin Hanafiyya).", "Annabi ﷺ ya koyar da ita kamar surar Alqur'ani."),
        "dua_sajdah_tilawah" to DuaText("Sajdah ta Karatu", "Fuskata ta yi sujada ga wanda ya halicce ta kuma ya fitar da jinta da ganinta da karfinsa da ikonsa.", "A cikin sujadar karatu.", "Annabi ﷺ ya faxi haka a cikin sujadar karatu da dare."),
        "dua_after_witr" to DuaText("Bayan Witr", "Tsarki ya tabbata ga Sarki mafi tsarki.", "Sau uku bayan sallamar witiri, ana daga murya a karo na uku.", "Annabi ﷺ ya fadi haka bayan witri."),
        "dua_tahajjud_nur" to DuaText("Addu'ar Budaddiyar Tahajjud", "Ya Allah godiya ta tabbata gareka; Kai ne Majiɓincin sammai da ƙasa da abin da ke cikinsu. Gõdiya ta tabbata a gare Ka. Kai ne hasken sammai da ƙasa da abin da ke cikinsu. Gõdiya ta tabbata a gare Ka. Kai ne Gaskiya Alkawarinka gaskiyane, haduwa da kai gaskiyane, kalmarka gaskiya ce, Aljanna gaskiya ce, Jahannama gaskiya ne, Annabi Muhammadu ﷺ gaskiya ne, Sa’a gaskiya ce.", "Idan aka fara sallar isha'i (tahajjud) (bangaren bude addu'a).", "Annabi ﷺ ya karanta wannan akan tashin tahajjud (cikakken addu'a yana cikin Bukhari)."),
        "dua_rabba_jibrail" to DuaText("Kayi mini jagora a cikin Al'amuran da ake jayayya", "Ya Allah Ubangijin Jibrilu da Mika'il da Israfila, Mahaliccin sammai da kassai, Masanin fake da bayyane! Ka yi hukunci a tsakãnin bãyinKa a cikin abin da suka kasance sunã sãɓã wa jũna. Ka shiryar da ni da izninKa zuwa ga gaskiya a cikin abin da aka sãɓã wa jũna a kansa. Lalle ne Kai, Kana shiryar da wanda Kake so zuwa ga tafarki madaidaici.", "A farkon tahajjud - don shiriya zuwa ga gaskiya a cikin sabani.", "Annabi ﷺ ya fara sallar dare da wannan addu'ar."),
        "dua_going_to_mosque_nur" to DuaText("Tafiya zuwa Masallaci (Dua na Haske)", "Ya Allah ka sanya haske a cikin zuciyata, haske a idanuna, haske a cikin kunnuwana, haske a kan damana, haske a kan haguna, haske samana, haske a kasana, haske a gabana, haske a bayana, ka sanya min haske.", "Yayin da za a je masallacin Asuba.", "Annabi ﷺ ya karanta wannan lokacin da zai fita sallah."),
        "dua_waswasa_salah" to DuaText("Waswasa Lokacin Sallah (Khinzab)", "Ina neman tsarin Allah daga Shaidan La'ananne.", "Idan wasuwasi na shaidan sun zo lokacin sallah, a nemi tsari da bushe-bushe tofa da sauki zuwa hagu sau uku.", "Uthman bn Abil-'As (RA) ya aikata haka sai waswasi suka tafi."),
        "dua_alimal_ghayb" to DuaText("Masanin gaibi", "Ya Allah Masanin fake da bayyane, Mahaliccin sammai da kassai, Ubangijin dukkan komai! Ina shaidawa babu abin bautawa da gaskiya sai Kai. Ina neman tsarinka daga sharrin kaina, da sharrin Shaidan da shirkansa.", "Safiya, maraice da kuma kafin barci - Annabi ﷺ ya koya wa Abubakar (RA).", "Kariya daga sharrin kai da na Shaidan."),
        "dua_fitratil_islam" to DuaText("Akan Fitar Musulunci", "Mun wayi gari a kan fitinar Musulunci, a kan kalmar ikhlasi, a kan addinin Annabinmu Muhammadu ﷺ da tafarkin babanmu Ibrahim (AS), mai gaskiya kuma musulmi, kuma ba ya cikin mushrikai.", "Da safe.", "Sabunta imani kowace safiya."),
        "dua_amsayna_fitrah" to DuaText("Maraice akan Fitar Musulunci", "Mun yi magariba a kan fitr Musulunci, da lafazin ikhlasi, a kan addinin Annabinmu Muhammadu ﷺ da tafarkin babanmu Ibrahim (AS), mai gaskiya kuma musulmi, kuma ba ya cikin mushrikai.", "Da yamma.", "Sabunta imani kowane maraice."),
        "dua_tahleel_10_fajr" to DuaText("Tahlil Goma Bayan Fajr da Maghrib", "Babu abin bautawa da gaskiya sai Allah, Shi kadai, ba tare da abokin tarayya ba. Nasa ne mulki kuma nasa gõdiya take. Yanã rãyarwa kuma Yanã kashẽwa, kuma Shĩ, a kan kõme, Mai ĩkon yi ne.", "Sau goma bayan Asuba (da Maghrib), kafin ka tashi daga zamanka ko magana.", "Kyawawan ayyuka goma, shafe zunubai goma, darajoji goma da aka daukaka da kariya daga shaidan duk yini."),
        "dua_la_hawla_kanz" to DuaText("Taskar Jannah", "Babu wani ƙarfi da ƙarfi face wurin Allah.", "Sau da yawa, a kowane lokaci.", "Yana daga cikin taskokin Aljannah."),
        "dua_four_beloved_words" to DuaText("Kalmomi Hudu Mafi Soyayya", "Tsarki ya tabbata ga Allah, dukkan godiya ta tabbata ga Allah, babu abin bautawa da gaskiya sai Allah, kuma Allah shi ne mafi girma.", "Kalmomin mafi soyuwa ga Allah.", "Sun fi soyuwa ga Annabi ﷺ fiye da duk abin da rana ta fito a kansa."),
        "dua_two_light_words" to DuaText("Kalmomi Biyu Haske akan Harshe", "Tsarki ya tabbata ga Allah, kuma gõdiya ta tabbata a gare Shi. Tsarki ya tabbata ga Allah Mabuwayi.", "Haske akan harshe, mai nauyi akan Sikeli.", "Masoyi ga Mai rahama, mai haske ga harshe, mai nauyi a kan sikeli. (Hadisin Bukhari na karshe)"),
        "dua_ya_dhal_jalal" to DuaText("Ya Dhal-Jalali wal-Ikram", "Ya Ma'abucin Girma da Girmamawa!", "Rike shi a cikin dua - koyarwar Annabi ﷺ.", "Annabi ﷺ ya ce: ku yi riko da ‘Ya Dhal-Jalali wal-Ikram’."),
        "dua_sleep_wadatu_janbi" to DuaText("Da Sunan Ka Na Kwanta", "A cikin sunanka, Ubangijina, na kwanta gefe na, da sunanka kuma na tashi. Idan Ka karvi raina, ka yi masa rahama, idan kuma Ka sake ta, ka kiyaye ta kamar yadda Ka kare bayinka salihai.", "Bayan yayi kura ya kwanta.", "Aiwatar da ran mutum ga Allah kafin barci."),
        "dua_sleep_khalaqta_nafsi" to DuaText("Ka Halicci Raina", "Ya Allah ka halicci raina kuma zaka dauka. Mutuwarta da rayuwarta naka ne. Idan Ka rãyar da shi, to, ka tsare shi, kuma idan Ka kashe shi, to, ka gãfarta masa. Ya Allah ina rokonka lafiya.", "Kafin barci - Ibn Umar ya ruwaito (RA).", "Annabi ﷺ yayi umarni da fadin haka lokacin kwanciya barci."),
        "dua_sleep_atamana" to DuaText("Godiya Kafin Barci", "Dukkan godiya ta tabbata ga Allah wanda ya ciyar da mu, ya shayar da mu, ya wadatar da mu, ya ba mu matsuguni. Nawa ne kuma ba su da wanda zai ishe su ko ba su mafaka.", "Lokacin kwanciya barci.", "Annabi ﷺ ya fadi haka lokacin da zai kwanta barci."),
        "dua_sleep_rabbas_samawat" to DuaText("Ubangijin sammai - Biyan Bashi", "Ya Allah Ubangijin sammai da kasa da Al'arshi mabuwayi, Ubangijinmu kuma Ubangijin dukkan komai, mai raba iri da dabino, mai saukar da Attaura da Injila da Furkan! Ina neman tsarinka daga sharrin duk abin da Ka rike makwarkwacinsa. Ya Allah Kai ne Na Farko, babu komai a gabanka; Kai ne na qarshe, babu komai a bayanKa; Kai ne bayyananne, babu wani abu a samanKa; Kai ne Boye, babu wani abu da yake boye gareka. Ka daidaita mana bashinmu, ka 'yantar da mu daga talauci.", "Kafin barci, kwance a gefen dama - karantar da Fatimah (RA).", "Addu'ar samun sauki daga bashi da wahala."),
        "dua_sleep_fear" to DuaText("Tsoro ko rashin kwanciyar hankali a cikin Barci", "Ina neman tsari da kalmomin Allah cikakku daga fushinsa da azabarsa, da sharrin bayinsa, da waswasin shaidanu da zuwa gare ni.", "Lokacin jin tsoro ko rashin jin daɗi a cikin barci.", "Yin haka, abin ba zai cutar da shi ba."),
        "dua_waking_afani" to DuaText("Wayyo: Ya Maida Raina", "Dukkan godiya ta tabbata ga Allah wanda ya kyautatawa jikina, ya mayar da raina gareni, kuma ya bani ikon ambatonsa.", "Akan tashi.", "Godiya ga sabon safiya."),
        "dua_allahu_rabbi" to DuaText("Allah, Allah ne Ubangijina", "Allah, Allah ne Ubangijina; Ba ni hada shi da komai.", "A cikin bakin ciki ko damuwa - Annabi ﷺ ya koya wa Asma bint Umays (RA).", "Riko da tauhidi a lokutan wahala."),
        "dua_rahmataka_arju" to DuaText("Rahmarku Ina Fata", "Ya Allah rahamarka ce nake fata, don haka kada ka bar ni ga kaina ko da kiftawar ido, ka gyara min dukkan al'amura na. Babu abin bautawa face Kai.", "Addu'ar wanda yake cikin damuwa (Da'awat al-makrub).", "Annabi ﷺ ya kira ta da dua na wanda ke cikin damuwa."),
        "dua_against_enemy_ahzab" to DuaText("Akan Sojojin Makiya", "Ya Allah Mai saukar da Littafi, Mai gaggawar sakamako! Kayar da 'yan tawaye. Ya Allah ka karya su, ka girgiza su.", "Against abokan gaba - da dua na Yakin na Confederates.", "Addu'ar Annabi ﷺ akan makiya."),
        "dua_anta_adudi" to DuaText("Kai ne Goyon bayana", "Ya Allah Kai ne Mataimaki na kuma Mai taimakona. Da Kai nake yin shiri, da Kai nake gaba, kuma da Kai nake yin yãƙi.", "Kafin takara ko babban kalubale.", "Annabi ﷺ ya fadi haka a yakin."),
        "dua_ikfinihim" to DuaText("Ya Isar Ni Da Su", "Ya Allah Ka isar min da su duk yadda Ka so.", "Akan sharrin azzalumai - dua na yaron a cikin labarin Mutanen Rago.", "Allah ya tseratar da yaron daga azzalumai."),
        "dua_qadarullah" to DuaText("Lokacin Wani Mummuna Ya Faru", "Al'amarin Allah ne, kuma Ya aikata abin da Yake so.", "Lokacin da wani abu mara dadi ya faru, maimakon a ce 'idan kawai'.", "'Idan kawai' ya buɗe kofa ga Shaidan."),
        "dua_ala_kulli_hal" to DuaText("Yabo A Kowanne Hali", "Dukkan godiya ta tabbata ga Allah a kowane hali.", "Lokacin da abin da ba a so ya faru.", "Annabi ﷺ ya faxi haka akan fuskantar wani abu da yake qi."),
        "dua_dogs_barking" to DuaText("Karnuka Masu Ji Suna Yi Da Dare", "Ina neman tsarin Allah daga Shaidan La'ananne.", "A kan jin karnuka suna ihu ko ihun jaki da dare.", "Suna ganin abin da ba ku gani."),
        "dua_leaving_home_adilla" to DuaText("Ku Gujewa Bata", "Ya Allah ina neman tsarinka don kada in bata ko a batar da ni, kada in zame ko a karkace ni, kada in yi zalunci ko a zalunce ni, kada in yi wauta ko a yi min wauta.", "Lokacin fita daga gida - Ummu Salamah ta ruwaito (RA).", "Annabi ﷺ yana karanta wannan a duk lokacin da ya fita daga gidansa."),
        "dua_ascending_descending" to DuaText("Tafi Da Saukowa", "Allah ne Mafi girma (lokacin hawan). - Tsarki ya tabbata ga Allah (lokacin sauka).", "A cikin tafiya, ku ce 'Allahu Akbar' idan za ku hau, kuma 'Subhanallahi' idan kuna saukowa.", "Ayyukan Sahabbai (RA) yayin tafiya."),
        "dua_traveller_sahar" to DuaText("Addu'ar Matafiya Kafin Alfijir", "Mai sauraro ya ji (kuma ya isar da) godiyarmu ga Allah da ni'imarSa a kanmu. Ya Ubangijinmu, Ka raka mu, kuma Ka yi mana ni’ima, (na faxi) ina neman tsarin Allah daga wuta.", "A kan tafiya, kafin alfijir.", "Annabi ﷺ ya faxi haka kafin fitowar alfijir yayin tafiya."),
        "dua_zawwadakallah" to DuaText("Ga Matafiyi: Allah Ya Azurta Takawa", "Allah ya azurta ku da takawa domin tafiyarku, Ya gafarta muku zunubanku, Ya sauwake muku a duk inda kuke.", "Lokacin bankwana da matafiyi.", "Annabi ﷺ ya ba da wannan addu'ar ga wani da ke shirin tafiya."),
        "dua_traveller_to_resident" to DuaText("Matafiyi Zuwa Wadanda Ke Tsayawa A Bayansu", "Ina ba ku amana ga Allah, wanda amana ba ta ta'azzara a gare shi.", "Matafiyi ya faxi lokacin yin bankwana da iyali.", "Da amanar iyali ga Allah."),
        "dua_entering_village" to DuaText("Shiga Gari ko Kauye", "Ya Allah Ubangijin sammai bakwai da inuwarsu, Ubangijin kassai bakwai da abin da suke xauke da su, Ubangijin shaixanu da abin da suke batarwa, Ubangijin iskoki da abin da suke watsewa! Muna rokonka alherin wannan gari da al'ummarta, kuma muna neman tsarinka daga sharrinta, da sharrin mutanensa da sharrin abin da ke cikinsa.", "Kafin shiga gari ko birni.", "Annabi ﷺ yana karanta wannan a duk lokacin da ya so shiga gari."),
        "dua_vehicle_stumbles" to DuaText("Lokacin da Motar ta yi Tushe", "Da sunan Allah.", "Lokacin da dutsen ko abin hawa ya zame ko ya yi tuntuɓe, maimakon a ce 'Shaiɗan ya halaka'.", "Fadin Bismillah yana sanya Shaidan ya ragu da girman kuda."),
        "dua_ajz_kasal_haram" to DuaText("Kubuta daga rauni da tsufa", "Ya Allah ina neman tsarinka daga tawaya da kasala, da tsoro da tsufa, da fitinun rayuwa da mutuwa, da azabar kabari.", "Cikakken addu'ar mafaka ta yau da kullun.", "A dua Annabi ﷺ yayi akai-akai."),
    )
}
